+        #[cfg(feature = "lane-profile")] crate::lane_profile::mark(crate::lane_profile::BROAD);
         self.broad_phase()?;
+        #[cfg(feature = "lane-profile")] crate::lane_profile::mark(crate::lane_profile::NARROW);
         self.narrow_phase()?;
+        #[cfg(feature = "lane-profile")] crate::lane_profile::mark(crate::lane_profile::ISLANDS);
         self.wake_and_join();
+        #[cfg(feature = "lane-profile")] crate::lane_profile::mark(crate::lane_profile::SETUP);
         solver::solve(self, dt)?;
+        #[cfg(feature = "lane-profile")] crate::lane_profile::mark(crate::lane_profile::POST_SOLVE_VALIDATION);
         if self.bodies.iter().any(|body| !finite_body(body) || !nonzero_rotation(body.xf.q)) || !finite_solver_caches(self) { return Err(PhysicsError::ArithmeticOverflow); }
+        #[cfg(feature = "lane-profile")] crate::lane_profile::mark(crate::lane_profile::SLEEP);
         self.sleep(dt);
+        #[cfg(feature = "lane-profile")] crate::lane_profile::mark(crate::lane_profile::POST_SLEEP_VALIDATION);
         if self.bodies.iter().any(|body| !finite_body(body) || !nonzero_rotation(body.xf.q)) { return Err(PhysicsError::ArithmeticOverflow); }
         Ok(())
     }
